         for (Carta carta : comunitarias) {
             mensaje.append(carta.toString()).append(" | ");
         }
         if (!comunitarias.isEmpty()) {
             mensaje.setLength(mensaje.length() - 3);
         }
         InterfazUtil.mostrarMensaje(mensaje.toString());
     }

