            int minimo = "Pre-Flop".equals(fase) ? bigBlind : 1;
            int cantidad = view.solicitarCantidad(
                    "¿Cuánto quieres apostar? (min " + minimo + ", max " + jugador.getSaldo() + "): ",
                    minimo, jugador.getSaldo());
