+                carta("K", "Corazones"), carta("K", "Picas"));
+
+        EvaluarManos.ResultadoEvaluacion resultado =
+                EvaluarManos.evaluarCombinacion(cartas);
+
+        assertEquals("Full", resultado.nombreJugada);
