+                carta("A", "Picas"), carta("A", "Corazones"), carta("A", "Diamantes"),
+                carta("K", "Picas"), carta("K", "Corazones")));
+        EvaluarManos.ResultadoEvaluacion trio = EvaluarManos.evaluarCombinacion(List.of(
+                carta("A", "Picas"), carta("A", "Corazones"), carta("A", "Diamantes"),
