                .sorted((a, b) -> b.get(0).getValorNumerico() - a.get(0).getValorNumerico())
                .toList();

        if (pares.size() >= 2) {
            List<Carta> dosPares = new ArrayList<>();
            dosPares.addAll(pares.get(0));
