import static org.junit.jupiter.api.Assertions.*;

class JugadoresTest {

    @Test
    void crearUnJugador_shouldBeInInitialState() {
        Jugador jugador = new Jugador("Ana", 1000);

        assertEquals("Ana", jugador.getNombre());
